    if exceed:
        # group consecutive 2h intervals
        groups=[]; cur=[]; prev=None
        for t,temp in exceed:
            if prev and (t-prev)>dt.timedelta(hours=2):
                groups.append(cur); cur=[]
            cur.append((t,temp)); prev=t
        if cur: groups.append(cur)
        for g in groups:
            print(' ',g[0][0], 'to', g[-1][0], 'n',len(g),'temps',round(min(x[1] for x in g),2),round(max(x[1] for x in g),2))
