import csv, collections, datetime as dt
from pathlib import Path
base=Path('/app/dataset')
def num(s): return float(str(s).replace(',','.'))
limits={'frozen':-10,'meat':4,'dairy':6,'dry':35}
by=collections.defaultdict(list)
with open(base/'temperature_logs.csv', newline='') as f:
    for r in csv.DictReader(f):
        t=dt.datetime.strptime(r['timestamp'],'%Y-%m-%d %H:%M:%S')
        by[r['zone'].lower()].append((t,num(r['temperature_c']), r['zone']))
for z, vals in sorted(by.items()):
    vals=sorted(vals)
    lim=limits[z]
    exceed=[(t,temp,orig) for t,temp,orig in vals if temp>lim]
    print('\nZONE',z,'rows',len(vals),'limit',lim,'min',min(v for _,v,_ in vals),'max',max(v for _,v,_ in vals),'exceed',len(exceed))
    if exceed:
        groups=[]; cur=[]; prev=None
        for t,temp,orig in exceed:
            if prev and (t-prev)>dt.timedelta(hours=2):
                groups.append(cur); cur=[]
            cur.append((t,temp,orig)); prev=t
        if cur: groups.append(cur)
